// Zero-dependency static site generator for NEXA. Run: node build.mjs  -> ./dist
import { mkdirSync, writeFileSync, cpSync, rmSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { company, services, industries, faqCategories, faqBy, process as steps, DISCLAIMER } from './src/data.mjs';
import { esc, icon, ico, icoB, layout, pageHero, crumbs, checks, ctaBand, svcGroups, indGroups, socLinks, homeHeroImage } from './src/lib.mjs';
import { brand } from './src/brands.mjs';
import { heroArt, flowArt, panelArt } from './src/art.mjs';
import { latestPosts } from './src/blogger.mjs';
import { meetings, meetPicker, calendarPanel, checklistTool, bookingFaq, meetStrip, wizard } from './src/booking.mjs';
import { jobs as allJobs } from './src/content/jobs.mjs';
import { heroStats, testimonials, testimonialsAreSamples } from './src/content/social-proof.mjs';
import { sec, head, statBand, iconCards, stepsBlock, faqBlock, quickFacts, banner, chipNav, compare, fitLists, standards, models, modelCards, serviceInputs, industryInputs, industryApproach, industryFaqs, areaCards, needFinder, slug } from './src/blocks.mjs';

const OUT = 'dist';
rmSync(OUT, { recursive: true, force: true }); mkdirSync(OUT, { recursive: true }); cpSync('public', OUT, { recursive: true });
const urls = []; const today = new Date().toISOString().slice(0, 10);
const write = (route, html, { index = true, file } = {}) => {
  const p = join(OUT, file || (route === '/' ? 'index.html' : join(route.replace(/^\//, ''), 'index.html')));
  mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, html); if (index) urls.push(route);
};
const svc = Object.fromEntries(services.map((s) => [s.slug, s])); const ind = Object.fromEntries(industries.map((i) => [i.slug, i]));
const hasImg = (n) => existsSync(join('public/assets/img', n));
const media = (n, v, alt) => (hasImg(n) ? `<img src="/assets/img/${n}" alt="${esc(alt)}" loading="lazy" width="800" height="670">` : panelArt(v, alt));
const notice = `<p class="notice">${esc(DISCLAIMER)}</p>`;
const fmtDate = (d) => new Date(d + 'T00:00:00Z').toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });
const faqLd = (qs) => ({ '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: qs.map(([q, a]) => ({ '@type': 'Question', name: q, acceptedAnswer: { '@type': 'Answer', text: a } })) });
const svcCard = (s, i) => `<a class="card reveal" data-d="${i % 3}" href="/services/${s.slug}"><span class="num">${String(i + 1).padStart(2, '0')}</span><span class="ico">${icon(s.icon)}</span><h3>${esc(s.title)}</h3><p>${esc(s.short)}</p><span class="link-arrow">Learn more ${icon('arrow-right')}</span></a>`;
/* on-page search + filter (behaviour in site.js: [data-filter]) */
const fitem = (html, cat, text) => html.replace(/^<(a|div|details)(?=[\s>])/, (m, t) => `<${t} data-fitem data-cat="${esc(cat)}" data-text="${esc(text.toLowerCase())}" `);
const toolbar = ({ id, target, label, ph, chips = [], noun, extra = '' }) => `<div class="toolbar toolbar--f" data-filter="#${target}"><div class="search-field"><label class="sr-only" for="${id}">${esc(label)}</label>${icon('search')}<input id="${id}" type="search" data-fsearch placeholder="${esc(ph)}" autocomplete="off" enterkeyhint="search"></div>${chips.length ? `<div class="chips" role="group" aria-label="${esc(label)}: filter by category"><button type="button" class="chip" data-fcat="" aria-pressed="true">All</button>${chips.map((c) => `<button type="button" class="chip" data-fcat="${esc(c)}" aria-pressed="false">${esc(c)}</button>`).join('')}</div>` : ''}<p class="fcount" data-fcount data-noun="${esc(noun)}" aria-live="polite"></p>${extra}</div>`;
const noMatch = `<div class="empty" data-fnone hidden><h3>No matches found</h3><p>Try different words or clear the filter, or <a href="/contact">ask us directly</a>.</p></div>`;

/* ---------- Forms (Formspree) ---------- */
const FORMSPREE = 'https://formspree.io/f/mpqvnlnb';
const FORM_SUBJECT = { contact: 'Contact enquiry', outsourcing: 'Outsourcing enquiry', 'job-application': 'Job application' };
const field = (id, label, { type = 'text', req = true, ph = '', ac = '' } = {}) => `<div><label for="${id}">${label}${req ? ' <span class="req" aria-hidden="true">*</span>' : ''}</label><input id="${id}" name="${id}" type="${type}" ${req ? 'required' : ''} ${ac ? `autocomplete="${ac}"` : ''} placeholder="${esc(ph)}"></div>`;
const sel = (id, label, opts, req = false) => `<div><label for="${id}">${label}${req ? ' <span class="req" aria-hidden="true">*</span>' : ''}</label><select id="${id}" name="${id}" ${req ? 'required' : ''}><option value="">Select…</option>${opts.map((o) => `<option>${esc(o)}</option>`).join('')}</select></div>`;
const consent = `<label class="check"><input type="checkbox" name="consent" value="yes" required><span>I agree to NEXA using the information I provide to respond to my enquiry, as described in the <a href="/privacy-policy">Privacy Policy</a>.</span></label>`;
const formOpen = (name, success, extra = '') => `<form class="form" name="${name}" method="POST" action="${FORMSPREE}" ${extra} data-formspree data-success="${esc(success)}"><input type="hidden" name="form_name" value="${name}"><input type="hidden" name="_subject" value="NEXA website: ${FORM_SUBJECT[name] || name}"><input type="hidden" name="_next" value="${company.site}/thank-you"><p class="hp" aria-hidden="true"><label>Do not fill this out <input name="_gotcha" tabindex="-1" autocomplete="off"></label></p>`;
const formClose = (label) => `<div class="form-status" role="status" aria-live="polite"></div><button class="btn btn--navy" type="submit"><span class="lbl">${label}</span></button></form>`;
const contactForm = () => `${formOpen('contact', 'Thank you. Your enquiry has been received and our team will respond by email.')}
<div class="row">${field('full_name', 'Full name', { ac: 'name' })}${field('email', 'Email', { type: 'email', ac: 'email' })}</div>
<div class="row">${field('phone', 'Phone (optional)', { type: 'tel', req: false, ac: 'tel' })}${sel('service', 'Service of interest', services.map((s) => s.title))}</div>
${sel('enquiry_type', 'Enquiry type', ['General enquiry', 'Request a consultation', 'Request a proposal', 'Partnership', 'Other'])}
<div><label for="message">Message <span class="req" aria-hidden="true">*</span></label><textarea id="message" name="message" required minlength="10" maxlength="4000"></textarea></div>${consent}${formClose('Send Enquiry')}`;
const osList = ['Remote bookkeeping', 'Bank and balance-sheet reconciliations', 'Accounts payable and receivable support', 'Month-end closing assistance', 'Financial reporting support', 'Excel financial models and dashboards', 'Management accounts preparation', 'Recurring accounting operations', 'Accounting workflow documentation'];
const outsourcingForm = () => `${formOpen('outsourcing', 'Thank you. Your outsourcing enquiry has been received and our team will be in touch by email.')}
<div class="row">${field('full_name', 'Name', { ac: 'name' })}${field('email', 'Business email', { type: 'email', ac: 'email' })}</div>
<div class="row">${field('company', 'Company name', { ac: 'organization' })}${field('country', 'Country', { ac: 'country-name' })}</div>
${sel('business_type', 'Business type', ['SME / operating business', 'Accounting or bookkeeping firm', 'Professional service provider', 'E-commerce business', 'Other'], true)}
<fieldset class="fieldset-box"><legend>Services required</legend><div class="opts">${osList.map((s, i) => `<label class="check"><input type="checkbox" name="services" value="${esc(s)}" id="os${i}"><span>${esc(s)}</span></label>`).join('')}</div></fieldset>
<div class="row">${sel('transaction_volume', 'Approx. monthly transactions (optional)', ['Under 100', '100 – 500', '500 – 2,000', 'Over 2,000', 'Not sure'])}${field('accounting_software', 'Accounting software (optional)', { req: false, ph: 'e.g. Excel, QuickBooks, Xero' })}</div>
<div><label for="message">Message (optional)</label><textarea id="message" name="message" maxlength="4000"></textarea></div>${consent}${formClose('Submit Outsourcing Enquiry')}`;

