<section class="section"><div class="container grid g3">${[['shield', 'Professional values', 'Integrity, accuracy and responsibility in every task.'], ['book', 'Learning', 'Work that develops practical accounting and advisory skills.'], ['users', 'Teamwork', 'Clear communication and respect for each colleague’s role.']].map(([i, h, p], k) => `<div class="panel reveal" data-d="${k}"><span class="ico">${icon(i)}</span><h3>${h}</h3><p class="muted" style="margin:0">${p}</p></div>`).join('')}</div></section>
