/* ---------- Legal ---------- */
const review = `<p class="notice"><strong>Legal review recommended.</strong> This page describes how this website currently operates. NEXA should have it reviewed by a qualified legal adviser to confirm it meets applicable Nepalese and other relevant requirements before relying on it.</p>`;
const mail = `<a href="mailto:${company.email}">${company.email}</a>`;
const legal = {
  'privacy-policy': ['Privacy Policy', `<p>Last updated: ${today}</p><h2>Information we collect</h2><ul><li><strong>Contact enquiries:</strong> name, email, optional phone, service of interest, enquiry type and message.</li><li><strong>Outsourcing enquiries:</strong> name, business email, company, country, business type, services required, optional volume and software, and message.</li><li><strong>Job applications:</strong> name, email, optional phone, cover letter or message, and your uploaded CV.</li><li><strong>Meeting bookings:</strong> the name, email and details you enter in the booking calendar, which is provided by Calendly.</li></ul><h2>Why we use it</h2><p>To respond to your enquiry, assess an engagement or application, and keep records of our communications.</p><h2>Storage and processing</h2><p>Form submissions are processed by Formspree, a third-party form service, and delivered to NEXA by email. Formspree may keep a copy of submissions on its systems under its own privacy terms. Meeting bookings are handled by Calendly, which loads only after you choose a meeting type and processes your booking details under its own privacy notice. Our blog is published separately at blog.nexa.com.np on Google’s Blogger platform, which has its own privacy practices. Our website is hosted by Netlify, and web fonts are loaded from Google Fonts.</p><h2>Access</h2><p>Enquiries and applications are accessible only to authorised NEXA personnel. We do not publish them.</p><h2>Retention</h2><p>We keep enquiries and applications only as long as needed for the purpose collected. NEXA should state its exact retention periods here after review.</p><h2>Your requests</h2><p>You may ask us to access, correct or delete your information by emailing ${mail}.</p><h2>Cookies</h2><p>See our <a href="/cookie-policy">Cookie Policy</a>.</p><h2>Contact for privacy enquiries</h2><p>${mail}</p>${review}`],
  'terms-of-use': ['Terms of Use', `<h2>Use of this website</h2><p>This website provides general information about NEXA’s services. By using it you agree to these terms.</p><h2>No professional advice</h2><p>Content is general in nature and is not tax, legal, accounting or investment advice for your circumstances. Engagements are governed by a separate written scope.</p><h2>Accuracy</h2><p>We aim for accuracy but do not warrant that content is complete or current. Verify regulatory information with the relevant authority.</p><h2>Intellectual property</h2><p>Website content is owned by or licensed to NEXA. Do not reproduce it without permission.</p><h2>Limitation</h2><p>To the extent permitted by law, NEXA is not liable for loss arising from reliance on website content.</p><h2>Contact</h2><p>${mail}</p>${review}`],
  disclaimer: ['Disclaimer', `<p>${esc(DISCLAIMER)}</p><p>Nothing on this website guarantees tax outcomes, government approvals, loan approvals, investment returns or any other result. Information is general and should not replace professional advice specific to your situation.</p>${review}`],
  'cookie-policy': ['Cookie Policy', `<h2>What this site stores</h2><p>This website does not set advertising or analytics cookies. Web fonts are loaded from Google Fonts, which may receive your IP address. Our hosting provider may process technical request data (such as IP address) for delivery and security.</p><p>The booking calendar on the Book a Meeting page is provided by Calendly. It loads only after you choose a meeting type and may set its own cookies, governed by Calendly’s cookie policy. Our blog at blog.nexa.com.np is hosted on Blogger and may set cookies under Google’s policies.</p><h2>Changes</h2><p>If analytics or other cookies are added, this policy will be updated and a consent mechanism provided where required.</p><h2>Contact</h2><p>${mail}</p>${review}`],
};
for (const [slug0, [t, html]] of Object.entries(legal)) write(`/${slug0}`, layout({ title: `${t} | NEXA Advisory & Consulting`, desc: `${t} for NEXA Advisory & Consulting Pvt. Ltd.`, path: `/${slug0}`, body: `${pageHero('LEGAL', t, '', [[t]])}<section class="section"><div class="container prose">${html}</div></section>
<section class="section section--alt"><div class="container"><h2 style="font-size:1.4rem">Other policies</h2>${chipNav(Object.entries(legal).filter(([k]) => k !== slug0).map(([k, [n]]) => [`/${k}`, n]), 'Related policies')}</div></section>
${ctaBand('Questions About This Policy?', 'If anything here is unclear, or you would like to make a request about your information, write to us.', ['Contact NEXA', '/contact'], ['Back to Home', '/'], { eyebrow: 'NEED CLARIFICATION', points: false, wa: 'Hello NEXA, I have a question about your website policies.' })}` }));

/* ---------- 404, sitemap, robots ---------- */
write('/404', layout({ title: 'Page not found | NEXA', desc: 'Page not found.', path: '/404', noindex: true, body: `${pageHero('404', 'We couldn’t find that page', 'The page may have moved or the address may be mistyped.', [['Page not found']], `<div class="btn-row"><a class="btn btn--navy" href="/">Go to homepage</a><a class="btn btn--ghost" href="/contact">Contact us</a></div>`)}
${sec(head('POPULAR PAGES', 'Perhaps one of these will help') + `<div class="ind-grid">${[['calculator', 'Services', '/services'], ['building', 'Industries', '/industries'], ['globe', 'Outsourcing', '/outsourcing'], ['shield', 'Why NEXA', '/why-nexa'], ['users', 'About NEXA', '/about'], ['book', 'Blog & Insights', company.blog], ['calendar', 'Book a Meeting', '/book'], ['chat', 'FAQs', '/faqs'], ['mail', 'Contact', '/contact']].map(([i, t, h]) => `<a class="ind" href="${h}">${icon(i)}<span>${esc(t)}</span></a>`).join('')}</div>`)}
${ctaBand('Can’t Find What You Need?', 'Tell us what you were looking for and we will point you in the right direction.', ['Contact NEXA', '/contact'], ['Explore Our Services', '/services'], { eyebrow: 'NEED A HAND?', points: false })}` }), { index: false, file: '404.html' });
/* ---------- site search index (powers the header search; built from the same data as the pages) ---------- */
const clip = (t, n = 150) => (t.length > n ? t.slice(0, n - 1).replace(/\s+\S*$/, '') + '…' : t);
const pagesIdx = [['Services', '/services', 'All services across accounting, tax, advisory and specialised support.', 1], ['Industries', '/industries', 'Sectors NEXA can support, from SMEs to NGOs.', 1], ['Outsourcing', '/outsourcing', 'Remote accounting and finance support for firms and international businesses.', 1], ['Why NEXA', '/why-nexa', 'How we work: scope, documentation, communication and confidentiality.', 0], ['About NEXA', '/about', 'Vision, mission, values and practice areas.', 0], ['Contact', '/contact', 'Send an enquiry or reach us by email or WhatsApp.', 1], ['Careers', '/careers', 'Vacancies and how to apply.', 0], ['Book a Meeting', '/book', 'Book a physical, group or one-on-one meeting with NEXA.', 1], ['Blog & Insights (blog.nexa.com.np)', company.blog, 'Articles on accounting, tax and compliance on our blog.', 0], ['FAQs', '/faqs', 'Answers on services, process, outsourcing, careers and privacy.', 0], ['Privacy Policy', '/privacy-policy', 'How we handle information you send us.', 0], ['Terms of Use', '/terms-of-use', 'Terms for using this website.', 0], ['Disclaimer', '/disclaimer', 'Limits of the general information on this site.', 0], ['Cookie Policy', '/cookie-policy', 'How this site uses cookies.', 0]];
const searchIndex = [
  ...services.map((x, n) => ({ t: x.title, u: `/services/${x.slug}`, c: 'Service', d: clip(x.short), k: [...x.includes, ...x.needs].join(' '), p: n < 5 ? 1 : 0 })),
  ...industries.map((x) => ({ t: x.name, u: `/industries/${x.slug}`, c: 'Industry', d: clip(x.headline || x.intro || ''), k: (x.challenges || []).join(' '), p: 0 })),
  ...faqCategories.flatMap(([c, qs]) => qs.map(([q, a]) => ({ t: q, u: `/faqs#faq-${slug(c)}`, c: 'FAQ', d: clip(a), k: `${c} ${a}`, p: 0 }))),
  ...pagesIdx.map(([t, u, d, pp]) => ({ t, u, c: 'Page', d, k: '', p: pp })),
  ...blogPosts.map((x) => ({ t: x.title, u: x.url, c: 'Article', d: clip(x.excerpt || ''), k: x.cat || '', p: 0 })),
  ...jobsLive.map((x) => ({ t: x.title, u: `/careers/${x.slug}`, c: 'Career', d: clip(x.summary || ''), k: `${x.department || ''} ${x.location || ''} ${x.type || ''}`, p: 0 })),
];
mkdirSync(join(OUT, 'assets'), { recursive: true });
writeFileSync(join(OUT, 'assets', 'search-index.json'), JSON.stringify(searchIndex));
writeFileSync(join(OUT, 'sitemap.xml'), `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls.map((u) => `<url><loc>${company.site}${u}</loc><lastmod>${today}</lastmod></url>`).join('\n')}\n</urlset>\n`);
writeFileSync(join(OUT, 'robots.txt'), `User-agent: *\nAllow: /\nDisallow: /thank-you\nDisallow: /careers/apply/\n\nSitemap: ${company.site}/sitemap.xml\n`);
console.log(`Built ${urls.length} indexable pages (${blogPosts.length} blog posts shown, ${jobsLive.length} vacancies) -> ${OUT}/`);
